candidates.raw:
    if ((wheels == NULL) || (momentum_body_nms == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16)) {
        *momentum_body_nms = (adcs_vec3_t){0, 0, 0};
        return ADCS_E_RANGE;
    }

    adcs_vec3_t total_h = {0, 0, 0};
    adcs_vec3_t normalized_axis;

    for (size_t i = 0; i < count; ++i) {
        const adcs_wheel_t *wheel = &wheels[i];

        // Check axis_body: finite and nonzero
        if (!adcs_is_finite_vec3(&wheel->axis_body)) {
            *momentum_body_nms = (adcs_vec3_t){0, 0, 0};
            return ADCS_E_RANGE;
        }

        // Normalize axis to check if it's non-zero (degenerate) and get unit vector
        if (adcs_vec3_normalize(&wheel->axis_body, ADCS_EPS_NORM, &normalized_axis) != ADCS_OK) {
            *momentum_body_nms = (adcs_vec3_t){0, 0, 0};
            return ADCS_E_RANGE;
        }

        // Check inertia: finite and > 0
        if (!isfinite(wheel->inertia_kg_m2) || (wheel->inertia_kg_m2 <= 0.0)) {
            *momentum_body_nms = (adcs_vec3_t){0, 0, 0};
            return ADCS_E_RANGE;
        }

        // Check speed: finite
        if (!isfinite(wheel->speed_rad_s)) {
            *momentum_body_nms = (adcs_vec3_t){0, 0, 0};
            return ADCS_E_RANGE;
        }

        // Compute h_k = J_k * omega_k * a_k
        double magnitude = wheel->inertia_kg_m2 * wheel->speed_rad_s;
        adcs_vec3_t h_k = adcs_vec3_scale(&normalized_axis, magnitude);

        // Accumulate
        total_h = adcs_vec3_add(&total_h, &h_k);
    }

    *momentum_body_nms = total_h;
    return ADCS_OK;
}

